{
  "findings": [
    {
      "check_id": "CKV_AZURE_3",
      "title": "Ensure that 'enable_https_traffic_only' is enabled",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account explicitly sets enable_https_traffic_only to false, allowing insecure HTTP traffic which exposes data in transit to interception."
    },
    {
      "check_id": "CKV_AZURE_59",
      "title": "Ensure that Storage accounts disallow public access",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Public network access is not restricted (public_network_access_enabled defaults to true), potentially exposing the storage account to the internet if no other controls are in place."
    },
    {
      "check_id": "CKV2_AZURE_40",
      "title": "Ensure that Storage Accounts use replication",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The account_replication_type is set to LRS (Locally Redundant Storage), which does not provide geo-redundancy and may fail compliance requirements for critical data availability."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Ensure storage account is configured without blob anonymous access",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Blob public access is not explicitly disabled (allow_blob_public_access defaults to true), risking unintended exposure of container or blob data."
    },
    {
      "check_id": "CKV2_AZURE_38",
      "title": "Ensure soft-delete is enabled on Azure storage account",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Soft delete policies are not configured, meaning accidental or malicious deletion of blobs cannot be recovered."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                     = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name      = azurerm_resource_group.smart_grid_rg.name\n  location                 = azurerm_resource_group.smart_grid_rg.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n  enable_https_traffic_only = true\n  public_network_access_enabled = false\n  allow_blob_public_access   = false\n\n  blob_properties {\n    versioning_enabled       = true\n    change_feed_enabled      = true\n\n    delete_retention_policy {\n      days = 7\n    }\n\n    container_delete_retention_policy {\n      days = 7\n    }\n  }\n}",
  "fix_summary": "Enabled HTTPS-only traffic, switched replication to GRS for geo-redundancy, disabled public network access and blob public access, and added blob properties to enforce versioning and soft-delete retention policies."
}
